-- Practice datasets (loaded on top of seed.sql). Each has deliberate gotchas: NULLs, orphans, ties, gaps, hierarchies.
DROP TABLE IF EXISTS enrollments; DROP TABLE IF EXISTS courses; DROP TABLE IF EXISTS students;
DROP TABLE IF EXISTS ratings; DROP TABLE IF EXISTS movies; DROP TABLE IF EXISTS daily_sales;
DROP TABLE IF EXISTS web_events; DROP TABLE IF EXISTS users; DROP TABLE IF EXISTS transactions; DROP TABLE IF EXISTS accounts; DROP TABLE IF EXISTS categories;
CREATE TABLE students (student_id INTEGER PRIMARY KEY, name TEXT, major TEXT, enrolled_year INTEGER);
CREATE TABLE courses (course_id INTEGER PRIMARY KEY, title TEXT, dept TEXT, credits INTEGER);
CREATE TABLE enrollments (student_id INTEGER, course_id INTEGER, grade INTEGER, term TEXT);
